import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';

/**
 * Calculate the total amount for one line (qty × unitPrice, in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate invoice totals (subtotal and total in cents).
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return { subtotal, total: subtotal };
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate format (YYYY-MM-DD)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime()) || date.toISOString().split('T')[0] !== issueDate) {
    return fail('DATE_INVALID');
  }

  // Validate lines array is not empty
  if (!lines || lines.length === 0) return fail('NO_LINES');

  // Validate and build lines with product info
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  };

  return ok(invoice);
}

/**
 * Add or update a line on a draft invoice.
 * If the SKU exists, increase its quantity; otherwise, add a new line.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists on invoice
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const updatedInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(updatedInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  if (!invoice.lines.some((line) => line.sku === sku)) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const updatedInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(updatedInvoice);
}

